style.css:
@-moz-document domain("roblox.com") {
/* General body styling */
    body {
        background-color: #f0f6ff !important;
        color: #7ec8e3 !important;
    }

    /* Headings and titles */
    h1, h2, h3, h4, h5, h6 {
        color: #7ec8e3 !important;
    }

    /* Navbar and menus */
    .navbar, .header, .menu, .game-name {
        background-color: #e1ecf9 !important;
        color: #7ec8e3 !important;
    }

    /* Links */
    a {
        color: #5ab0db !important;
    }
    a:hover {
        color: #3a9ccc !important;
    }

    /* Buttons */
    button, .btn-primary {
        background-color: #cbe6ff !important;
        color: #006fa4 !important;
        border: none !important;
    }

    button:hover, .btn-primary:hover {
        background-color: #b4ddff !important;
        color: #004a6f !important;
    }

    /* Game cards and containers */
    .game-card, .container, .game-tile, .section {
        background-color: #ffffff !important;
        border: 1px solid #cde7fa !important;
        border-radius: 10px !important;
        color: #7ec8e3 !important;
    }

    /* Fix dark elements */
    .dark-theme, .theme-dark {
        background-color: #f0f6ff !important;
        color: #7ec8e3 !important;
    }

    /* Textareas and inputs */
    input, textarea {
        background-color: #ffffff !important;
        color: #5ab0db !important;
        border: 1px solid #cde7fa !important;
    }
}
